from rest_framework import status, viewsets
from rest_framework.decorators import action, api_view
from rest_framework.response import Response

from .models import User
from .passwords import generate_password
from .permissions import IsAdminRole, IsStaffRole
from .serializers import UserSerializer


@api_view(["GET"])
def me(request):
    return Response(UserSerializer(request.user).data)


class ManagedAccountViewSet(viewsets.ModelViewSet):
    """Accounts of a single role whose passwords are generated by the server.

    The generated password is returned once (on create and on reset) so the
    coach can hand it to the person; it is never stored in plain text.
    Deleting an account deactivates it, keeping training history intact.
    """

    serializer_class = UserSerializer
    managed_role: str = ""

    def get_queryset(self):
        queryset = User.objects.filter(role=self.managed_role)
        if self.request.query_params.get("include_inactive") != "true":
            queryset = queryset.filter(is_active=True)
        return queryset

    def create(self, request, *args, **kwargs):
        serializer = self.get_serializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        password = generate_password()
        user = User(**serializer.validated_data, role=self.managed_role)
        user.set_password(password)
        user.save()
        data = {**self.get_serializer(user).data, "generated_password": password}
        return Response(data, status=status.HTTP_201_CREATED)

    def perform_destroy(self, instance):
        instance.is_active = False
        instance.save(update_fields=["is_active"])

    @action(detail=True, methods=["post"], url_path="reset-password")
    def reset_password(self, request, pk=None):
        user = self.get_object()
        password = generate_password()
        user.set_password(password)
        user.save(update_fields=["password"])
        return Response({"id": user.id, "generated_password": password})


class StudentViewSet(ManagedAccountViewSet):
    managed_role = User.Role.STUDENT
    permission_classes = [IsStaffRole]


class CoachViewSet(ManagedAccountViewSet):
    managed_role = User.Role.COACH
    permission_classes = [IsAdminRole]
